function chatbotContexto() {
  const kanban = document.getElementById('crm-secao-kanban');
  if (kanban && kanban.style.display !== 'none' && kanban.innerHTML) return 'kanban';
  if (document.getElementById('crm-sidebar-painel') || /funil-vendas/.test(location.pathname)) return 'crm';
  return 'geral';
}

function montarChatbotWidget() {
  if (document.getElementById('chatbot-launcher')) return;
  const robo = '<svg style="width:26px;height:26px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;" viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="9" width="16" height="11" rx="3"/><circle cx="12" cy="4.5" r="1.5"/><line x1="12" y1="6" x2="12" y2="9"/><circle cx="9" cy="14.5" r="1.2" fill="currentColor"/><circle cx="15" cy="14.5" r="1.2" fill="currentColor"/><line x1="2" y1="13" x2="2" y2="16"/><line x1="22" y1="13" x2="22" y2="16"/></svg>';
  const wrap = document.createElement('div');
  wrap.innerHTML = `
    <button class="chatbot-launcher" id="chatbot-launcher" onclick="toggleChatbot()" title="Assistente Eagles — perguntas frequentes" aria-label="Abrir assistente de perguntas frequentes">${robo}</button>
    <div class="chatbot-window" id="chatbot-window" role="dialog" aria-label="Assistente Eagles">
      <div class="chatbot-header"><span class="chatbot-header-titulo">${robo.replace('width:26px;height:26px', 'width:18px;height:18px')} Assistente Eagles</span><button type="button" onclick="toggleChatbot()" aria-label="Fechar">&times;</button></div>
      <div class="chatbot-body" id="chatbot-body"></div>
      <div class="chatbot-faq" id="chatbot-faq"></div>
      <div class="chatbot-input-row">
        <input type="text" id="chatbot-input" placeholder="Ou digite sua dúvida..." onkeydown="if(event.key==='Enter'){chatbotEnviar();}">
        <button type="button" onclick="chatbotEnviar()" aria-label="Enviar"><svg style="width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;" viewBox="0 0 24 24"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg></button>
      </div>
    </div>
  `;
  document.body.appendChild(wrap);
}

function chatbotRenderFaq(categoriaId) {
  const el = document.getElementById('chatbot-faq');
  if (!el) return;
  const ctx = categoriaId || chatbotContexto();
  const ordem = CHATBOT_FAQ.slice().sort((a, b) => (a.id === ctx ? -1 : b.id === ctx ? 1 : 0));
  const atual = ordem[0];
  el.innerHTML = `
    <div class="chatbot-faq-abas">${ordem.map((c) => `<button type="button" class="${c.id === atual.id ? 'ativo' : ''}" onclick="chatbotRenderFaq('${c.id}')">${escapeHtml(c.titulo)}</button>`).join('')}</div>
    <div class="chatbot-faq-lista">${atual.perguntas.map((q, i) => `<button type="button" onclick="chatbotPerguntaFaq('${atual.id}', ${i})">${escapeHtml(q.p)}</button>`).join('')}</div>`;
}

function chatbotPerguntaFaq(catId, i) {
  const cat = CHATBOT_FAQ.find((c) => c.id === catId);
  const q = cat && cat.perguntas[i];
  if (!q) return;
  chatbotAdicionarMsg('user', q.p);
  setTimeout(() => chatbotAdicionarMsg('bot', q.r), 250);
}

function abrirChatbot() {
  fecharTodosDropdowns();
  const win = document.getElementById('chatbot-window');
  if (win) win.classList.add('open');
  chatbotIniciarSeNecessario();
  chatbotRenderFaq();
}

function toggleChatbot() {
  const win = document.getElementById('chatbot-window');
  if (!win) return;
  win.classList.toggle('open');
  if (win.classList.contains('open')) { chatbotIniciarSeNecessario(); chatbotRenderFaq(); }
}

function chatbotIniciarSeNecessario() {
  if (CHATBOT_INICIADO) return;
  CHATBOT_INICIADO = true;
  chatbotAdicionarMsg('bot', 'Oi! Eu sou o assistente da Eagles Labz. Escolha uma pergunta abaixo ou digite a sua dúvida.');
}

function chatbotAdicionarMsg(tipo, texto) {
  const body = document.getElementById('chatbot-body');
  if (!body) return;
  const div = document.createElement('div');
  div.className = 'chatbot-msg ' + tipo;
  div.textContent = texto;
  body.appendChild(div);
  body.scrollTop = body.scrollHeight;
}

function chatbotNormalizar(t) {
  return String(t || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

// Casa por palavra inteira (sem acento): "cor" não casa mais com
// "corrigir", "oi" não casa com "foi".
function chatbotCasa(texto, padrao) {
  const p = chatbotNormalizar(padrao);
  if (!p) return false;
  return (' ' + texto + ' ').includes(' ' + p + ' ');
}

function chatbotResponder(pergunta) {
  const p = chatbotNormalizar(pergunta);
  // 1) perguntas frequentes, começando pelas da tela atual
  const ctx = chatbotContexto();
  const cats = CHATBOT_FAQ.slice().sort((a, b) => (a.id === ctx ? -1 : b.id === ctx ? 1 : 0));
  const irrelevantes = new Set(['como', 'que', 'uma', 'um', 'meu', 'minha', 'para', 'pra', 'com', 'dos', 'das', 'no', 'na', 'eu', 'faco', 'qual', 'o', 'a', 'de', 'do', 'da', 'e', 'os', 'as', 'se', 'ou']);
  const palavras = p.split(' ').filter((w) => w.length > 2 && !irrelevantes.has(w));
  let melhor = null, melhorPontos = 0;
  cats.forEach((c, ci) => c.perguntas.forEach((q) => {
    const alvo = ' ' + chatbotNormalizar(q.p) + ' ';
    const pontos = palavras.filter((w) => alvo.includes(' ' + w) || alvo.includes(w + ' ')).length - ci * 0.01;
    if (pontos > melhorPontos) { melhor = q; melhorPontos = pontos; }
  }));
  if (melhor && melhorPontos >= 2) return melhor.r;
  // 2) base de respostas antiga (ERP e assuntos gerais)
  for (const item of CHATBOT_KB) {
    if (item.padroes.some((padrao) => chatbotCasa(p, padrao))) return item.resposta;
  }
  if (melhor && melhorPontos >= 1) return melhor.r;
  return 'Não tenho certeza sobre isso ainda. Dê uma olhada nas perguntas frequentes aqui embaixo, consulte a Central de Ajuda (no ícone "?") ou fale com o Suporte pelo WhatsApp — fica no mesmo menu.';
}

function chatbotEnviar() {
  const input = document.getElementById('chatbot-input');
  if (!input) return;
  const texto = input.value.trim();
  if (!texto) return;
  chatbotAdicionarMsg('user', texto);
  input.value = '';
  setTimeout(() => {
    chatbotAdicionarMsg('bot', chatbotResponder(texto));
  }, 350);
}

function chatbotPerguntaRapida(texto) {
  const input = document.getElementById('chatbot-input');
  if (input) input.value = texto;
  chatbotEnviar();
}

function abrirSuporteWhatsApp() {
  fecharTodosDropdowns();
  const numero = '5511946784626';
  const texto = encodeURIComponent('PRECISO DE AJUDA COM A PLATAFORMA EAGLES');
  window.open(`https://wa.me/${numero}?text=${texto}`, '_blank');
}

// =====================================================================
// ---------- Inicialização comum de página ----------
// =====================================================================

// Trava o zoom por pinça/duplo-toque no celular. Só faz efeito em telas de
// toque de verdade — no computador esses eventos de toque nunca disparam,
// então isso nunca interfere no zoom do navegador (Ctrl +/-) de quem usa
// mouse e teclado.
function bloquearZoomMobile() {
  document.addEventListener('touchmove', (e) => {
    if (e.touches && e.touches.length > 1) e.preventDefault();
  }, { passive: false });

  let ultimoToque = 0;
  document.addEventListener('touchend', (e) => {
    const agora = Date.now();
    if (agora - ultimoToque <= 300) e.preventDefault();
    ultimoToque = agora;
  }, { passive: false });
}

function initPaginaComum(activeKey) {
  aplicarTemaSalvo();
  renderTopbar(activeKey);
  initFirebase();
  montarChatbotWidget();
  bloquearZoomMobile();
  // initPerfilWatch() e initBuscaGlobalWatch() NÃO entram aqui de propósito:
  // elas dependem de TENANT_ID, que só fica pronto depois que o login
  // termina de resolver (dentro de protegerPagina). Chamá-las aqui faria
  // elas rodarem cedo demais, sempre em modo local. Ver protegerPagina.
}

// =====================================================================
// ---------- Motor genérico de cadastros simples ----------
// =====================================================================
// Usado por: Produtos, Vendedores, Funcionários, Pedidos de venda,
// Objetos de postagem, Contratos, Pedido de compras, Notas fiscais de
// entrada, Lançamentos de estoque, Conferência de estoque.

const CADASTROS_REGISTRO = {};
let CADASTROS_DATA = {};
let CADASTRO_MODAL_MODULO = null;
let CADASTRO_MODAL_ID = null;

function registrarModuloCadastro(moduloKey, def) {
  CADASTROS_REGISTRO[moduloKey] = def;
}

function initModuloCadastro(moduloKey) {
  const def = CADASTROS_REGISTRO[moduloKey];
  cloudWatch(def.storageKey, def.seed(), (data) => {
    CADASTROS_DATA[moduloKey] = data;
    renderCadastroTabela(moduloKey);
  });
  const form = document.getElementById(def.formNovoId);
  if (form) form.addEventListener('submit', (e) => { e.preventDefault(); handleNovoCadastroSimples(moduloKey); });
}

function renderCadastroTabela(moduloKey, dadosFiltrados) {
  const def = CADASTROS_REGISTRO[moduloKey];
  const tbody = document.getElementById(def.tbodyId);
  if (!tbody) return;
  const dados = dadosFiltrados || CADASTROS_DATA[moduloKey] || [];
  if (!dados.length) {
    tbody.innerHTML = emptyCadastroHtml(`openModal('${def.modalNovoId}')`, def.colunas.length + 1);
    return;
  }
  tbody.innerHTML = dados.map((item) => {
    const cols = def.colunas.map((c) => `<td>${c.render ? c.render(item) : (item[c.key] !== undefined ? escapeHtml(item[c.key]) : '—')}</td>`).join('');
    const editarAttr = def.onEditarCustom ? `${def.onEditarCustom}('${item.id}')` : `abrirCadastroModal('${moduloKey}','${item.id}')`;
    const acoesHtml = def.renderAcoes
      ? def.renderAcoes(item)
      : `<button class="btn btn-small btn-ghost" onclick="${editarAttr}">Editar</button>
         <button class="btn btn-small btn-ghost" style="color:var(--danger);" onclick="excluirCadastroItem('${moduloKey}','${item.id}')">Excluir</button>`;
    return `<tr>${cols}<td style="white-space:nowrap; text-align:right;">${acoesHtml}</td></tr>`;
  }).join('');
}

function handleNovoCadastroSimples(moduloKey) {
  const def = CADASTROS_REGISTRO[moduloKey];
  const form = document.getElementById(def.formNovoId);
  // Usa o 1º valor válido de status/situação DESSE módulo como padrão —
  // cada módulo tem seu próprio vocabulário (ex: contrato usa
  // "vigente"/"encerrado", não "ativo"/"inativo"), então um valor fixo
  // pra todos os módulos mostrava rótulo errado ou "undefined" na tela.
  const campoStatus = def.fields.find((f) => (f.key === 'status' || f.key === 'situacao') && f.options && f.options.length);
  const novo = { id: genId(moduloKey.slice(0, 2)), criadoEm: new Date().toISOString(), atualizadoEm: new Date().toISOString() };
  if (campoStatus) novo[campoStatus.key] = campoStatus.options[0].value;
  def.fields.forEach((f) => {
    const el = form.querySelector(`[data-novo-key="${f.key}"]`);
    if (!el) return;
    novo[f.key] = f.type === 'checkbox' ? el.checked : el.value;
  });
  if (def.camposExtras) Object.assign(novo, def.camposExtras());
  CADASTROS_DATA[moduloKey] = CADASTROS_DATA[moduloKey] || [];
  CADASTROS_DATA[moduloKey].push(novo);
  cloudSet(def.storageKey, CADASTROS_DATA[moduloKey]);
  renderCadastroTabela(moduloKey);
  form.reset();
  closeModal(def.modalNovoId);
}

function renderFichaCampos(fields, item, editavel) {
  let html = '';
  let secaoAtual = null;
  fields.forEach((f) => {
    if (f.secao && f.secao !== secaoAtual) {
      secaoAtual = f.secao;
      html += `<div class="field full" style="margin-top:6px; margin-bottom:-4px;"><div style="font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:0.4px; color:var(--blue-text); border-top:1px solid var(--border); padding-top:14px;">${secaoAtual}</div></div>`;
    }
    html += renderCampoHtml(f, item ? item[f.key] : '', editavel);
  });
  return html;
}

function abrirCadastroModal(moduloKey, id) {
  CADASTRO_MODAL_MODULO = moduloKey;
  CADASTRO_MODAL_ID = id;
  const def = CADASTROS_REGISTRO[moduloKey];
  const item = (CADASTROS_DATA[moduloKey] || []).find((i) => i.id === id);
  if (!item) return;
  document.getElementById(def.modalEditTituloId).textContent = 'Editar ' + def.tituloItem;
  document.getElementById(def.modalEditCamposId).innerHTML = renderFichaCampos(def.fields, item, true);
  openModal(def.modalEditId);
}

function salvarCadastroModal() {
  const moduloKey = CADASTRO_MODAL_MODULO;
  const def = CADASTROS_REGISTRO[moduloKey];
  const item = (CADASTROS_DATA[moduloKey] || []).find((i) => i.id === CADASTRO_MODAL_ID);
  if (!item) return;
  Object.assign(item, lerCamposModal('#' + def.modalEditCamposId));
  item.atualizadoEm = new Date().toISOString();
  cloudSet(def.storageKey, CADASTROS_DATA[moduloKey]);
  renderCadastroTabela(moduloKey);
  closeModal(def.modalEditId);
}

function excluirCadastroItem(moduloKey, id) {
  const def = CADASTROS_REGISTRO[moduloKey];
  const item = (CADASTROS_DATA[moduloKey] || []).find((i) => i.id === id);
  if (!item) return;
  const nomeExibicao = item[def.campoNome] || 'este registro';
  confirmarAcao(`Excluir "${nomeExibicao}"? Essa ação não pode ser desfeita.`, () => {
    CADASTROS_DATA[moduloKey] = CADASTROS_DATA[moduloKey].filter((i) => i.id !== id);
    cloudSet(def.storageKey, CADASTROS_DATA[moduloKey]);
    renderCadastroTabela(moduloKey);
  });
}

